mapper.select:
SELECT sum(og.goods_price * og.ordeR_goods_num + og.shipping_fee - og.voucher_price) AS catTurnoverSelf, gc.cat_frist_parent_id AS firstCatId, date_format(ob.payment_time, '%Y-%m') AS catStatisticsTime FROM ${database.prefix.order}hou_order_goods og LEFT JOIN ${database.prefix.order}hou_order_base ob ON ob.order_id = og.order_id LEFT JOIN ${database.prefix.goods}hou_goods_cat gc ON og.goods_class_id = gc.cat_id WHERE ob.payment_time >= #{startTime}
AND ob.payment_time <= #{endTime}
AND ob.order_status IN (2, 3, 4, 5, 6) AND gc.cat_frist_parent_id IN (1000, 1006080506, 1006080309, 1006080236, 1006080730, 1006080325, 1006080654, 999) GROUP BY gc.cat_frist_parent_id, date_format( ob.payment_time, '%Y-%m' )
